import { adviceAddBundle, adviceAddItem } from "#base/ui/advice/advice-manager.js";
import { shouldSelect } from "#base/ui/advice/advice-support.js";

const TURN_WAIT = 20; // After how many turns when to select. (May be used with game speed to determine actual turn).
const TURN_START = 10; // On which turn should items start being selected (phased by turn offset).
const TURN_OFFSET = 12; // Which "phase" (from turn 1) to start checking.

adviceAddItem({
	id: "ADVICE_EXPLORATION_MILITARY_MILITARY_VICTORY",
	type: AdvisorTypes.MILITARY,
	onSelect: () => {
		return Game.turn == 1;
	},
});

adviceAddItem({
	id: "ADVICE_EXPLORATION_MILITARY_PEACE_DEALS",
	type: AdvisorTypes.MILITARY,
	onSelect: () => {
		let bCanMakePeace = false;
		const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
		if (player) {
			const PlayerList: PlayerLibrary[] = Players.getAlive();
			for (const otherPlayer of PlayerList) {
				if (otherPlayer.isMajor && otherPlayer.id != player.id) {
					if (player.Diplomacy?.isAtWarWith(otherPlayer.id)) {
						// canMakePeaceWith does not return a bool.  It returns a Result in case you need tooltip information.
						const peaceQueryResults: DiplomacyQueryResult = player.Diplomacy.canMakePeaceWith(
							otherPlayer.id,
							false,
						);
						if (peaceQueryResults.Success) {
							bCanMakePeace = true;
							break;
						}
					}
				}
			}
		}
		return bCanMakePeace;
	},
});

adviceAddBundle({
	id: "ADVICE_EXPLORATION_MILITARY_MISC",
	type: AdvisorTypes.MILITARY,
	pages: [
		"ADVICE_EXPLORATION_MILITARY_VICTORY_COUNTERPLAY",
		"ADVICE_EXPLORATION_MILITARY_NAVAL_UNITS",
		"ADVICE_EXPLORATION_MILITARY_SIEGE_UNITS",
		"ADVICE_EXPLORATION_MILITARY_PILLAGING",
		"ADVICE_EXPLORATION_MILITARY_FORTIFYING",
		"ADVICE_EXPLORATION_MILITARY_REINFORCING",
		"ADVICE_EXPLORATION_MILITARY_DISTANT_LANDS",
		"ADVICE_EXPLORATION_MILITARY_TRIUMPH",
	],
	priority: 100,
	delivery: "random",
	onSelect: () => {
		return shouldSelect(TURN_START, TURN_WAIT, TURN_OFFSET);
	},
});
